"""QQ-图片包加载：把单张图片和 zip/cbz/tar/tar.gz 图包按顺序逐张输出。"""

from __future__ import annotations

import io
import asyncio
import gzip
import hashlib
import json
import os
import re
import tarfile
import tempfile
import threading
import time
import zipfile
from collections import OrderedDict
from dataclasses import dataclass
from typing import Any, Iterable
from pathlib import Path

import torch
from PIL import Image, ImageOps, UnidentifiedImageError

import folder_paths

try:
    from aiohttp import web
    from server import PromptServer
except Exception:  # tests may run without the ComfyUI server
    web = None
    PromptServer = None


NODE_TYPE = "QQImagePackageLoader"
PACKAGE_IMAGE_EXTENSIONS = {
    ".jpg", ".jpeg", ".png", ".webp", ".bmp", ".gif", ".tif", ".tiff", ".avif",
}
PACKAGE_ARCHIVE_EXTENSIONS = {".zip", ".cbz", ".tar", ".gz", ".tgz", ".tar.gz"}
PACKAGE_EXTENSIONS = PACKAGE_IMAGE_EXTENSIONS | PACKAGE_ARCHIVE_EXTENSIONS
MAX_PACKAGE_IMAGES = 20_000
MAX_MEMBER_BYTES = 256 * 1024 * 1024
MAX_ARCHIVE_TOTAL_BYTES = 8 * 1024 * 1024 * 1024
MAX_IMAGE_PIXELS = 64_000_000

_MANIFEST_CACHE = OrderedDict()
_THUMBNAIL_CACHE = OrderedDict()
_CACHE_LOCK = threading.RLock()


@dataclass(frozen=True)
class PackageEntry:
    """One output image: either a direct image or a member inside an archive."""

    source: str
    member: str
    path: str


@dataclass(frozen=True)
class ImagePackageInfo:
    """Execution-scoped metadata used by the dedicated package saver."""

    source: str
    source_path: str
    source_kind: str
    source_extension: str
    output_stem: str
    member: str
    source_index: int
    entry_index: int
    source_total: int
    global_index: int
    total: int

    def ui(self) -> dict[str, Any]:
        return {
            "source": self.source,
            "source_path": self.source_path,
            "source_kind": self.source_kind,
            "extension": self.source_extension,
            "output_stem": self.output_stem,
            "member": _member_label(self.member),
            "source_index": self.source_index,
            "entry_index": self.entry_index,
            "source_total": self.source_total,
            "global_index": self.global_index,
            "total": self.total,
        }


def natural_key(value: str) -> tuple[Any, ...]:
    """Natural sort key: image2 precedes image10, using the full relative path."""
    return tuple(
        (1, int(part)) if part.isdigit() else (0, part.casefold())
        for part in re.split(r"(\d+)", value)
    )


def _extension(name: str) -> str:
    lower = str(name or "").lower()
    if lower.endswith(".tar.gz"):
        return ".tar.gz"
    return os.path.splitext(lower)[1]


def package_kind(filename: str) -> str | None:
    suffix = _extension(filename)
    if suffix in PACKAGE_IMAGE_EXTENSIONS:
        return "image"
    if suffix in PACKAGE_ARCHIVE_EXTENSIONS:
        return "archive"
    return None


def normalize_reference(value: Any) -> str:
    return str(value or "").strip().strip('"').replace("\\", "/")


def _within(root: str, relative: str) -> str:
    root = os.path.realpath(root)
    path = os.path.realpath(os.path.join(root, relative))
    if os.path.commonpath((root, path)) != root:
        raise ValueError("路径不能超出所选目录")
    return path


def _is_output_path(reference: str) -> bool:
    return str(reference or "").startswith("output::")


def resolve_reference(reference: str) -> str:
    """Resolve panel references and accept absolute paths when they already exist."""
    text = normalize_reference(reference)
    if os.path.isabs(text) and os.path.isfile(text):
        return os.path.realpath(text)
    raw = text[8:] if _is_output_path(text) else text
    roots = folder_paths.get_output_directory() if _is_output_path(text) else folder_paths.get_input_directory()
    path = _within(roots, raw)
    if not os.path.isfile(path):
        raise ValueError(f"找不到文件 {reference}")
    return path


def _safe_member_name(name: str) -> bool:
    normalized = normalize_reference(name)
    if not normalized or normalized in {".", ".."}:
        return False
    return not normalized.startswith("/") and ":" not in normalized and not any(
        part in {"", ".."} for part in normalized.split("/")
    )


def _member_label(name: str) -> str:
    return "/".join(part for part in normalize_reference(name).split("/") if part != ".")


def _cached_gzip(path: str, stat, image: bool = False) -> str:
    """Decompress once into ComfyUI temp; TAR members are subsequently seekable."""
    root = os.path.join(folder_paths.get_temp_directory(), "qq_image_packages")
    os.makedirs(root, exist_ok=True)
    key = hashlib.sha256(repr((path, stat.st_mtime_ns, stat.st_size)).encode()).hexdigest()
    target = os.path.join(root, key + (".image" if image else ".tar"))
    if os.path.isfile(target):
        return target
    limit = MAX_MEMBER_BYTES if image else MAX_ARCHIVE_TOTAL_BYTES
    fd, temporary = tempfile.mkstemp(dir=root, suffix=".part")
    try:
        total = 0
        with os.fdopen(fd, "wb") as output, gzip.open(path, "rb") as source:
            while chunk := source.read(1024 * 1024):
                total += len(chunk)
                if total > limit:
                    raise ValueError("GZ 解压大小超过限制")
                output.write(chunk)
        os.replace(temporary, target)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return target


def _zip_names(path: str) -> list[str]:
    names: list[str] = []
    total = 0
    with zipfile.ZipFile(path, "r") as archive:
        for info in archive.infolist():
            if info.is_dir():
                continue
            total += int(info.file_size)
            if total > MAX_ARCHIVE_TOTAL_BYTES:
                raise ValueError("压缩包解压总量超过 8GB 限制")
            name = _member_label(info.filename)
            if not _safe_member_name(name) or "/__MACOSX/" in f"/{name}/" or os.path.basename(name).startswith("."):
                continue
            if _extension(name) in PACKAGE_IMAGE_EXTENSIONS:
                if info.file_size > MAX_MEMBER_BYTES:
                    raise ValueError(f"包内图片过大：{name}")
                names.append(info.filename)
            if len(names) > MAX_PACKAGE_IMAGES:
                raise ValueError(f"单个图片包最多 {MAX_PACKAGE_IMAGES} 张图片")
    return sorted(set(names), key=lambda name: natural_key(_member_label(name)))


def _tar_names(path: str) -> dict[str, tuple[int, int]]:
    names = {}
    total = 0
    with tarfile.open(path, "r:*") as archive:
        for info in archive:
            if not info.isfile():
                continue
            total += int(info.size)
            if total > MAX_ARCHIVE_TOTAL_BYTES:
                raise ValueError("压缩包解压总量超过 8GB 限制")
            name = _member_label(info.name)
            if not _safe_member_name(name) or "/__MACOSX/" in f"/{name}/" or os.path.basename(name).startswith("."):
                continue
            if _extension(name) in PACKAGE_IMAGE_EXTENSIONS:
                if info.size > MAX_MEMBER_BYTES:
                    raise ValueError(f"包内图片过大：{name}")
                names[info.name] = (info.offset_data, info.size)
            if len(names) > MAX_PACKAGE_IMAGES:
                raise ValueError(f"单个图片包最多 {MAX_PACKAGE_IMAGES} 张图片")
    return dict(sorted(names.items(), key=lambda item: natural_key(_member_label(item[0]))))


def manifest_for(reference: str) -> dict[str, Any]:
    with _CACHE_LOCK:
        return _manifest_for(reference)


def _manifest_for(reference: str) -> dict[str, Any]:
    """Index an image/archive. Manifests are cached by path, mtime and size."""
    path = resolve_reference(reference)
    stat = os.stat(path)
    key = (os.path.realpath(path), int(stat.st_mtime_ns), int(stat.st_size))
    cached = _MANIFEST_CACHE.get(key)
    if cached is not None:
        _MANIFEST_CACHE.move_to_end(key)
        return cached
    kind = package_kind(path)
    data_path = path
    offsets = {}
    gzip_image = False
    if kind == "image":
        members = [""]
    elif kind == "archive":
        suffix = _extension(path)
        gzip_image = suffix == ".gz" and _extension(path[:-3]) in PACKAGE_IMAGE_EXTENSIONS
        if suffix in {".gz", ".tar.gz", ".tgz"}:
            data_path = _cached_gzip(path, stat, gzip_image)
        if gzip_image:
            members = [os.path.basename(path)[:-3]]
        elif suffix in {".zip", ".cbz"}:
            members = _zip_names(path)
        else:
            offsets = _tar_names(data_path)
            members = list(offsets)
        if not members:
            raise ValueError(f"图片包 {os.path.basename(path)} 中没有直接图片（不支持嵌套压缩包）")
    else:
        raise ValueError(f"不支持的文件类型：{os.path.basename(path)}")
    manifest = {
        "reference": normalize_reference(reference),
        "path": os.path.realpath(path),
        "kind": kind or "unknown",
        "members": members,
        "mtime_ns": int(stat.st_mtime_ns),
        "size": int(stat.st_size),
        "data_path": data_path,
        "offsets": offsets,
        "gzip_image": gzip_image,
    }
    _MANIFEST_CACHE[key] = manifest
    while len(_MANIFEST_CACHE) > 32:
        _MANIFEST_CACHE.popitem(last=False)
    return manifest


def _read_direct(path: str) -> bytes:
    if os.path.getsize(path) > MAX_MEMBER_BYTES:
        raise ValueError(f"图片过大：{os.path.basename(path)}")
    with open(path, "rb") as handle:
        return handle.read()


def _read_member(manifest: dict[str, Any], member: str) -> bytes:
    path = manifest["path"]
    suffix = _extension(path)
    if manifest["gzip_image"]:
        return _read_direct(manifest["data_path"])
    if suffix in {".zip", ".cbz"}:
        with zipfile.ZipFile(path, "r") as archive:
            info = archive.getinfo(member)
            if int(info.file_size) > MAX_MEMBER_BYTES:
                raise ValueError(f"包内图片过大：{member}")
            return archive.read(info)
    offset, size = manifest["offsets"][member]
    with open(manifest["data_path"], "rb") as handle:
        handle.seek(offset)
        return handle.read(size)


def read_entry_image(manifest: dict[str, Any], member: str) -> Image.Image:
    data = _read_direct(manifest["path"]) if not member else _read_member(manifest, member)
    try:
        image = Image.open(io.BytesIO(data))
        if image.width * image.height > MAX_IMAGE_PIXELS:
            image.close()
            raise ValueError(f"图片像素超过 {MAX_IMAGE_PIXELS} 限制")
        image.load()
    except (UnidentifiedImageError, OSError, ValueError) as exc:
        label = member or os.path.basename(manifest["path"])
        raise ValueError(f"无法解码图片 {label}") from exc
    return ImageOps.exif_transpose(image)


def tensor_from_image(image: Image.Image) -> torch.Tensor:
    image = image.convert("RGB")
    return (torch.from_numpy(__import__("numpy").array(image, copy=True)).to(dtype=torch.float32) / 255.0).unsqueeze(0)


def _first_image_member(manifest: dict[str, Any]) -> str:
    return manifest["members"][0]


def _thumbnail_bytes(reference: str, max_edge: int = 256, index: int = 0) -> bytes:
    manifest = manifest_for(reference)
    members = manifest["members"]
    position = int(index)
    member = members[position] if 0 <= position < len(members) else members[-1]
    path = manifest["path"]
    stat = os.stat(path)
    key = (os.path.realpath(path), int(stat.st_mtime_ns), int(stat.st_size), member, int(max_edge))
    cached = _THUMBNAIL_CACHE.get(key)
    if cached is not None:
        return cached
    image = None
    for candidate in [member] + [item for item in members if item != member]:
        try:
            with read_entry_image(manifest, candidate) as opened:
                image = opened.copy()
            break
        except ValueError:
            continue
    if image is None:
        raise ValueError("图片包中没有可解码的封面图片")
    image.thumbnail((max_edge, max_edge), Image.LANCZOS)
    buffer = io.BytesIO()
    image.convert("RGB").save(buffer, format="WEBP", quality=82, method=4)
    data = buffer.getvalue()
    _THUMBNAIL_CACHE[key] = data
    while len(_THUMBNAIL_CACHE) > 128:
        _THUMBNAIL_CACHE.popitem(last=False)
    return data


def parse_state(value: Any) -> dict[str, list[str]]:
    raw = value if isinstance(value, dict) else json.loads(str(value or "{}"))
    sources = raw.get("sources", []) if isinstance(raw, dict) else []
    if not isinstance(sources, list):
        raise ValueError("package_state.sources 必须是数组")
    result: list[str] = []
    for item in sources:
        reference = normalize_reference(item)
        if package_kind(reference) is None:
            raise ValueError(f"仅支持图片或 zip/cbz/tar/tar.gz：{reference}")
        if reference not in result:
            result.append(reference)
    return {"sources": result}


def parse_path_input(value: Any) -> list[str]:
    text = str(value or "").strip()
    if not text:
        return []
    parts = re.split(r"[\n,;]+", text)
    return [normalize_reference(part) for part in parts if part.strip()]


def package_entries(sources: Iterable[str]) -> list[PackageEntry]:
    entries: list[PackageEntry] = []
    manifests: dict[str, dict[str, Any]] = {}
    for source in sources:
        reference = normalize_reference(source)
        manifest = manifests.get(reference)
        if manifest is None:
            manifest = manifest_for(reference)
            manifests[reference] = manifest
        for member in manifest["members"]:
            entries.append(PackageEntry(source=reference, member=member, path=manifest["path"]))
            if len(entries) > MAX_PACKAGE_IMAGES:
                raise ValueError(f"所有图片包合计最多 {MAX_PACKAGE_IMAGES} 张图片")
    return entries


def _info_payload(reference: str) -> dict[str, Any]:
    manifest = manifest_for(reference)
    return {
        "reference": normalize_reference(reference),
        "kind": manifest["kind"],
        "name": os.path.basename(manifest["path"]),
        "count": len(manifest["members"]),
        "first": _member_label(manifest["members"][0]) if manifest["members"] else "",
        "size": manifest["size"],
    }


def _list_payload(folder: str = "", source: str = "input") -> dict[str, Any]:
    source_name = "output" if source == "output" else "input"
    root = folder_paths.get_output_directory() if source_name == "output" else folder_paths.get_input_directory()
    folder = normalize_reference(folder).strip("/")
    base = _within(root, folder)
    if not os.path.isdir(base):
        raise ValueError("目录不存在")
    folders: list[dict[str, Any]] = []
    files: list[dict[str, Any]] = []
    with os.scandir(base) as scanner:
        for entry in scanner:
            if entry.name.startswith("."):
                continue
            if entry.is_dir(follow_symlinks=False):
                folders.append({"name": entry.name, "path": f"{folder}/{entry.name}".lstrip("/")})
                continue
            if not entry.is_file(follow_symlinks=False):
                continue
            kind = package_kind(entry.name)
            if kind is None:
                continue
            stat = entry.stat()
            files.append({
                "name": entry.name,
                "path": ("output::" if source_name == "output" else "") + f"{folder}/{entry.name}".lstrip("/"),
                "kind": kind,
                "size": int(stat.st_size),
            })
    return {
        "folder": normalize_reference(folder),
        "source": source_name,
        "folders": sorted(folders, key=lambda item: natural_key(item["name"])),
        "files": sorted(files, key=lambda item: natural_key(item["name"])),
    }


def _register_routes() -> None:
    if PromptServer is None or web is None or not hasattr(PromptServer, "instance"):
        return
    server = PromptServer.instance
    if getattr(server, "_qq_image_package_routes", False):
        return

    @server.routes.get("/qq_image_packages/list")
    async def list_packages(request):
        try:
            return web.json_response(await asyncio.to_thread(_list_payload,
                request.query.get("folder", ""),
                request.query.get("source", "input"),
            ))
        except Exception as exc:
            return web.json_response({"error": str(exc)}, status=400)

    @server.routes.get("/qq_image_packages/info")
    async def package_info(request):
        try:
            return web.json_response(await asyncio.to_thread(_info_payload, request.query.get("reference", "")))
        except Exception as exc:
            return web.json_response({"error": str(exc)}, status=400)

    @server.routes.get("/qq_image_packages/thumbnail")
    async def package_thumbnail(request):
        try:
            max_edge = min(512, max(64, int(request.query.get("size", "256"))))
            index = max(0, int(request.query.get("index", "0") or 0))
            data = await asyncio.to_thread(_thumbnail_bytes, request.query.get("reference", ""), max_edge, index)
            return web.Response(body=data, content_type="image/webp")
        except Exception as exc:
            return web.json_response({"error": str(exc)}, status=400)

    server._qq_image_package_routes = True


_register_routes()


_IMAGE_SAVE_FORMATS = {
    ".jpg": "JPEG",
    ".jpeg": "JPEG",
    ".png": "PNG",
    ".webp": "WEBP",
    ".bmp": "BMP",
    ".gif": "GIF",
    ".tif": "TIFF",
    ".tiff": "TIFF",
    ".avif": "AVIF",
}


def _encoded_image(tensor: torch.Tensor, member_or_path: str) -> bytes:
    """Encode one image tensor using the original member's image format."""
    if tensor.ndim == 3:
        tensor = tensor.unsqueeze(0)
    if tensor.ndim != 4 or int(tensor.shape[0]) != 1:
        raise ValueError("图片包保存一次只能写入一张图像；当前批次不是 1")
    import numpy as np

    array = (tensor[0].clamp(0, 1).cpu().numpy() * 255).round().astype("uint8")
    image = Image.fromarray(array, mode="RGB")
    suffix = _extension(member_or_path)
    image_format = _IMAGE_SAVE_FORMATS.get(suffix)
    if image_format is None:
        raise ValueError(f"无法按原始图片格式保存：{suffix or '未知格式'}")
    buffer = io.BytesIO()
    try:
        image.save(buffer, format=image_format)
    except (ValueError, OSError) as exc:
        raise ValueError(f"当前 Pillow 不支持写入图片格式 {suffix}") from exc
    return buffer.getvalue()


def _safe_output_component(value: Any, fallback: str) -> str:
    text = str(value or fallback).strip()
    cleaned = re.sub(r'[\\/:*?"<>|]', "_", text)
    return cleaned or fallback


def _source_output_stem(source_path: str) -> str:
    base = os.path.basename(source_path)
    lowered = base.lower()
    if lowered.endswith(".tar.gz"):
        return base[:-7]
    if lowered.endswith((".tar", ".tgz")):
        return base[:-4]
    ending = _extension(base)
    return base[:-len(ending)] if ending else base


def _package_output_stems(sources: Iterable[str]) -> dict[str, str]:
    """Keep outputs separate when two selected packages have the same filename."""
    references = [normalize_reference(source) for source in sources]
    manifests = {reference: manifest_for(reference) for reference in references}
    counts: dict[str, int] = {}
    for manifest in manifests.values():
        key = os.path.basename(manifest["path"]).casefold()
        counts[key] = counts.get(key, 0) + 1
    result: dict[str, str] = {}
    for reference, manifest in manifests.items():
        stem = _source_output_stem(manifest["path"])
        filename = os.path.basename(manifest["path"]).casefold()
        if counts[filename] > 1:
            digest = hashlib.sha256(reference.encode("utf-8")).hexdigest()[:8]
            stem = f"{stem}-{digest}"
        result[reference] = stem
    return result


def _package_output_name(output_stem: str, source_path: str, suffix: str) -> str:
    ending = _extension(source_path)
    return f"{_safe_output_component(output_stem, _source_output_stem(source_path))}{_safe_output_component(suffix, '_edited')}{ending}"


def _write_zip(source: str, target: str, member: str, data: bytes) -> None:
    with zipfile.ZipFile(source, "r") as reader, zipfile.ZipFile(target, "w") as writer:
        for info in reader.infolist():
            if info.is_dir():
                writer.writestr(info, b"")
            elif _member_label(info.filename) != _member_label(member):
                writer.writestr(info, reader.read(info))
        new_info = zipfile.ZipInfo(member, date_time=time.localtime()[:6])
        new_info.compress_type = zipfile.ZIP_DEFLATED
        new_info.external_attr = 0o644 << 16
        writer.writestr(new_info, data)


def _write_tar(source: str, target: str, member: str, data: bytes, compressed: bool) -> None:
    mode = "w:gz" if compressed else "w"
    with tarfile.open(source, "r:*") as reader, tarfile.open(target, mode) as writer:
        for info in reader:
            if info.isfile() and _member_label(info.name) == _member_label(member):
                continue
            payload = reader.extractfile(info) if info.isfile() else None
            writer.addfile(info, payload)
        new_info = tarfile.TarInfo(member)
        new_info.size = len(data)
        new_info.mode = 0o644
        new_info.mtime = int(time.time())
        writer.addfile(new_info, io.BytesIO(data))


class QQImagePackageSaver:
    """按来源图包原格式保存当前结果；多个图包分别写入对应输出包。"""

    CATEGORY = "QQ/工具"
    FUNCTION = "save"
    OUTPUT_NODE = True
    RETURN_TYPES = ("IMAGE", "STRING")
    RETURN_NAMES = ("图像", "保存路径")
    DESCRIPTION = (
        "QQ-图片包加载的专用保存节点。根据「图包信息」识别当前图片来自哪个图包，"
        "并按原格式写入对应输出 zip/cbz/tar/tar.gz/tgz；单张图片按原图片格式保存。"
        "默认生成 *_edited 输出文件，不修改来源图片包；自动下一张会在同一输出包中累积替换。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "图像": ("IMAGE",),
                "图包信息": ("QQ_IMAGE_PACKAGE_INFO",),
                "输出目录": ("STRING", {"default": "qq_image_packages", "multiline": False}),
                "输出后缀": ("STRING", {"default": "_edited", "multiline": False}),
                "覆盖输出": ("BOOLEAN", {"default": True}),
            },
        }

    @classmethod
    def IS_CHANGED(cls, **_kwargs):
        return float("nan")

    def save(self, 图像, 图包信息, 输出目录="qq_image_packages", 输出后缀="_edited", 覆盖输出=True):
        if not isinstance(图包信息, ImagePackageInfo):
            raise ValueError("图包信息必须来自 QQ-图片包加载 节点")
        output_root = folder_paths.get_output_directory()
        relative_directory = str(输出目录 or "qq_image_packages").replace("\\", "/").strip("/")
        target_directory = Path(_within(output_root, relative_directory))
        target_directory.mkdir(parents=True, exist_ok=True)
        source_path = Path(图包信息.source_path)
        if not source_path.is_file():
            raise ValueError(f"来源图包不存在：{图包信息.source_path}")
        source_suffix = _extension(source_path.name)
        gzip_image = source_suffix == ".gz" and _extension(source_path.stem) in PACKAGE_IMAGE_EXTENSIONS
        target = target_directory / _package_output_name(图包信息.output_stem, source_path.name, 输出后缀)
        if os.path.realpath(target) == os.path.realpath(source_path):
            raise ValueError("输出文件不能与来源文件相同；请设置非空输出后缀")
        if target.exists() and not 覆盖输出:
            raise FileExistsError(f"输出文件已存在：{target}")
        data = _encoded_image(图像, 图包信息.member or source_path.name)
        base_archive = target if target.exists() else source_path
        fd, temporary_name = tempfile.mkstemp(prefix=".qq-package-", suffix=".part", dir=target_directory)
        os.close(fd)
        temporary = Path(temporary_name)
        try:
            if gzip_image:
                with open(temporary, "wb") as raw, gzip.GzipFile(fileobj=raw, mode="wb", mtime=0) as output:
                    output.write(data)
            elif 图包信息.source_kind == "image":
                temporary.write_bytes(data)
            elif source_suffix in {".zip", ".cbz"}:
                _write_zip(str(base_archive), str(temporary), 图包信息.member, data)
            elif source_suffix in {".tar", ".tar.gz", ".tgz", ".gz"}:
                _write_tar(str(base_archive), str(temporary), 图包信息.member, data, source_suffix != ".tar")
            else:
                raise ValueError(f"不支持的图包格式：{source_suffix}")
            os.replace(temporary, target)
        finally:
            if temporary.exists():
                temporary.unlink()
        # The output directory may be a drive letter mapped to a UNC mount.
        # os.path.relpath raises on Windows when target and output root resolve
        # to different mounts, so return the already-validated logical path.
        relative_path = "/".join(part for part in (relative_directory, target.name) if part)
        return {"ui": {"images": []}, "result": (图像, relative_path)}


class QQImagePackageLoader:
    """逐张加载图片/图片包；前端可在整个工作流完成后自动排下一张。"""

    CATEGORY = "QQ/工具"
    FUNCTION = "load"
    RETURN_TYPES = ("IMAGE", "INT", "INT", "QQ_IMAGE_PACKAGE_INFO")
    RETURN_NAMES = ("图像", "当前序号", "总张数", "图包信息")
    DESCRIPTION = (
        "漫画/艺术家图片包专用加载器。支持单张图片和 zip/cbz/tar/tar.gz 图包；"
        "压缩包只占一个卡牌格子，包内按完整相对路径自然排序，不支持嵌套压缩包。"
        "默认每次执行输出一张，配合前端「自动下一张」在工作流完成后自动排队，"
        "跑完停止。既可以从面板选择，也可以用 file_path 输入路径。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "package_state": ("STRING", {"default": "{\"sources\":[]}", "multiline": False}),
                "当前序号": ("INT", {"default": 1, "min": 1, "max": MAX_PACKAGE_IMAGES}),
                "自动下一张": ("BOOLEAN", {"default": True}),
            },
            "optional": {
                "file_path": ("STRING", {"forceInput": True, "tooltip": "可输入一个或多个路径（换行/逗号分隔）；接入后优先于面板选择。"}),
            },
            "hidden": {"unique_id": "UNIQUE_ID"},
        }

    @classmethod
    def IS_CHANGED(cls, package_state="{\"sources\":[]}", 当前序号=1, file_path=None, **_kwargs):
        # Re-evaluate metadata on manual runs and single-page loops as well.
        return float("nan")

    @classmethod
    def VALIDATE_INPUTS(cls, package_state="{\"sources\":[]}", file_path=None, input_types=None, **_kwargs):
        try:
            if file_path is None and input_types and "file_path" in input_types:
                return True
            sources = parse_path_input(file_path) or parse_state(package_state)["sources"]
            if not sources:
                if input_types and "file_path" in input_types:
                    return True
                return "请选择图片/图片包，或在 file_path 输入路径"
            entries = package_entries(sources)
            if not entries:
                return "没有可处理的图片"
        except Exception as exc:
            return str(exc)
        return True

    def load(self, package_state="{\"sources\":[]}", 当前序号=1, 自动下一张=True, file_path=None, unique_id=None):
        sources = parse_path_input(file_path) or parse_state(package_state)["sources"]
        if not sources:
            raise ValueError("请选择图片/图片包，或在 file_path 输入路径")
        entries = package_entries(sources)
        total = len(entries)
        index = int(当前序号 or 1)
        if not 1 <= index <= total:
            raise ValueError(f"当前序号超出范围：{index}/{total}")
        entry = entries[index - 1]
        manifest = manifest_for(entry.source)
        with read_entry_image(manifest, entry.member) as image:
            tensor = tensor_from_image(image)
        current = _member_label(entry.member) if entry.member else os.path.basename(entry.path)
        source_index = 0
        entry_index = 0
        source_total = len(manifest["members"])
        output_stems = _package_output_stems(sources)
        for source_position, source in enumerate(sources):
            source_manifest = manifest_for(source)
            if source_manifest is manifest:
                source_index = source_position + 1
                entry_index = source_manifest["members"].index(entry.member) + 1
                break
        info = ImagePackageInfo(
            source=entry.source,
            source_path=manifest["path"],
            source_kind=str(manifest["kind"]),
            source_extension=_extension(manifest["path"]),
            output_stem=output_stems[entry.source],
            member=entry.member,
            source_index=source_index,
            entry_index=entry_index,
            source_total=source_total,
            global_index=index,
            total=total,
        )
        result = (tensor, index, total, info)
        # 前端在 execution_success 后读取这份元数据，准确决定是否自动排下一张。
        return {
            "ui": {
                "qq_image_package": [{
                    "index": index,
                    "total": total,
                    "auto": bool(自动下一张),
                    "current": current,
                    "package": info.ui(),
                    "state": str(package_state),
                    "node_id": str(unique_id) if unique_id is not None else "",
                }],
            },
            "result": result,
        }


